WHERE
  { ?var2  wdt:P17  wde:Q252
      { ?var2 wdt:P31/(wdt:P279)* wde:Q34770
        VALUES ?var2 { wde:Q33960 }
      }
    UNION
      { ?var2 (wdt:P279)* wde:Q34770
